### 代码原文
```ts
326    /**
327     * 打开一场。
328     * @param id 会话号。
329     * @returns 会话对象。同一场永远交回同一个对象。
330     * @throws 没有这场时抛错。
331     */
332    open(id: string): Session {
333      //M 先查内存里已打开的会话对象，直接复用以保持运行开关和未入队消息一致。
334      const opened = this.openedSessions.get(id);
335      if (opened !== undefined) return opened;
336  
337      //M 库里的两块读出来，拼回一份记录。
338      const sql = 'SELECT meta, messages FROM sessions WHERE id = ?';
339      const query = this.ctx.resources.db.query(sql);
340      const stored = query.get(id) as { meta: string; messages: string } | null;
341  
342      //G 库里没有 → 抛错。
343      if (stored === null) {
344        throw new Error(`没有这场会话：${id}`);
345      }
346  
347      //M 解析磁盘元信息与对话历史重建会话实例，并放入 openedSessions 供同一场对话复用。
348      const meta = JSON.parse(stored.meta) as SessionMeta;
349      const messages = JSON.parse(stored.messages) as piAi.Message[];
350      const session = new Session({ ...meta, messages }, this.ctx);
351      this.openedSessions.set(id, session);
352      return session;
353    }
354  
```

### 解释
- 输入会话号；输出 Session，同一场永远交回同一个对象。
- 三步见下面三个子块。

