506    /**
507     * 推这场对话往下走，走到做完、停下或者出错为止。自己不往外抛。
508     * 谁都可以调：插件把话交给它以后、重启后接着跑。已经在转就直接返回，刚说的话下一步会带上。
509     * 副作用：发事件、调模型、执行工具、写库。
510     */
511    async run(): Promise<void> {
512      //G 已经在转 → return。
513      if (this.aborter !== undefined) return;
514  
515      //M 备好这一轮的取消开关，状态改成 running，跑循环；不管怎么结束都把开关收掉。
516      const aborter = new AbortController();
517      this.aborter = aborter;
518      this.change('running', '');
519      try {
520        await this.loop(aborter.signal);
521      } catch (error) {
522        //G 被喊停时请求是被掐断的，状态已经是 stopped；还是 running 才算出错。
523        if (this.row.state === 'running') {
524          const reason = textModule.getMessage(error);
525          this.change('failed', `出错了：${reason}`);
526        }
527      } finally {
528        this.aborter = undefined;
529      }
530  
531      //G 收尾的那一下又有人说话 → 再转一轮。喊停后慢工具还在收尾时来的话也在这里转，不然要等下一句话才处理。
532      if (this.inbox.length > 0) {
533        void this.run();
534      }
535    }
536  
```

### 解释
- 谁都可以调：插件把话交给它以后、重启后接着跑（src7/Main.ts 的 L214–L216）。
- 三步见下面三个子块。

