**行号：L537–L652**

### 代码原文
```ts
537    /**
538     * 循环本身：一步 = 调一次模型，加上执行它要的工具。不数步数，一直走到下面三种情况之一：
539     * 模型不再要工具（做完了）；有人喊停（stop()）；某个关口上有插件写了 stop。
540     * @param signal 这一轮的取消信号。
541     */
542    private async loop(signal: AbortSignal): Promise<void> {
543      //M step 只用来记这是第几步（给跟踪看），不拿它限制会话。
544      for (let step = 1; ; step += 1) {
545        //G 被喊停了 → 不往下走。
546        if (this.row.state !== 'running') return;
547  
548        //M 用户说了、还没接进对话的话，这时候接进去。
549        for (const waiting of this.inbox.splice(0)) {
550          this.append(waiting);
551        }
552  
553        //M 关口一，调模型之前：备好这一步的请求，交给插件挨个改（session/request）。
554        const request: ChatRequest = {
555          session: this,
556          model: this.row.model,
557          thinking: this.row.thinking,
558          system: [],
559          tools: this.ctx.tools.list(this.row.kind),
560          messages: [...this.row.messages],
561          signal,
562        };
563        await this.ctx.serial('session/request', request);
564  
565        //G 有插件喊停 → 不调模型，这一轮停在这里，理由写进 reply。
566        if (request.stop !== undefined) {
567          this.stop(request.stop);
568          return;
569        }
570  
571        //T 跟踪：调模型；插件已经给了回答（假模型）就写明没有调。
572        const vars = {
573          会话: this.id,
574          第几步: step,
575          模型: request.model,
576          对话几条: request.messages.length,
577        };
578        let doing = '调模型';
579        if (request.answer !== undefined) {
580          doing = '插件已经给了回答，不调模型';
581        }
582        this.ctx.emit('trace', 'Session.loop', doing, 'ctx.sessions.chat(request)', vars);
583  
584        //M 调模型（Sessions.chat，就在本文件上面）。插件已经给了回答（假模型）就不发请求。
585        let answer = request.answer;
586        if (answer === undefined) {
587          answer = await this.ctx.sessions.chat(request);
588        }
589  
590        //G 等模型的时候被喊停了 → 这次回答不要了。
591        if (this.row.state !== 'running') return;
592  
593        //M 关口二，模型回来之后：回答接进对话之前，带着回答交给插件挨个看（session/after-model）。
594        const answered: AnsweredRequest = { ...request, answer };
595        await this.ctx.serial('session/after-model', answered);
596  
597        //G 有插件喊停 → 这次回答不要了（里面要的工具也不执行），这一轮停在这里。
598        if (answered.stop !== undefined) {
599          this.stop(answered.stop);
600          return;
601        }
602  
603        //M 插件可能改了、换了回答，以最后这一份为准，接进对话。
604        answer = answered.answer;
605        this.append(answer);
606  
607        //M 从回答里挑出工具调用。
608        const calls = answer.content.filter((block): block is piAi.ToolCall => {
609          return block.type === 'toolCall';
610        });
611  
612        //M 模型没要工具 → 这一轮做完了，它说的就是回给用户的话。
613        if (calls.length === 0) {
614          const reply = piAi.contentText(answer.content);
615          this.change('done', reply);
616          return;
617        }
618  
619        //M 模型要了工具 → 一个个执行（关口三 session/before-tool 在 Tools.execute 里），结果接进对话，回到开头走下一步。
620        for (const call of calls) {
621          const executed = await this.ctx.tools.execute(call, this, signal);
622  
623          //M 关口四，工具执行之后：结果接进对话之前，交给插件挨个看（session/after-tool）。
624          const done: ToolDone = { session: this, call, outcome: executed };
625          await this.ctx.serial('session/after-tool', done);
626  
627          //M 插件可能改了结果，以改过的为准。
628          const outcome = done.outcome;
629  
630          //M 结果写成一条 toolResult：先是文字，后面跟着图片（有的话）。
631          const textBlock: piAi.TextContent = { type: 'text', text: outcome.text };
632          const images = outcome.images ?? [];
633          const result: piAi.Message = {
634            role: 'toolResult',
635            toolCallId: call.id,
636            toolName: call.name,
637            content: [textBlock, ...images],
638            isError: outcome.isError,
639            timestamp: Date.now(),
640          };
641          //M 把打包好的工具结果追加到对话历史并落库广播，供下一步继续喂给模型。
642          this.append(result);
643  
644          //G 有插件喊停 → 这一轮停在这里。结果已经接进对话（要和工具调用配对）；
645          //G   这一批后面的工具，Tools.execute 看到停了就不执行，只交回“未执行”接进对话。
646          if (done.stop !== undefined) {
647            this.stop(done.stop);
648          }
649        }
650      }
651    }
652  
```

### 解释
- 输入：这一轮的取消信号 signal。
- 六步见下面六个子块。

